pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        // Restrict _feeRate to the allowed range to avoid reverting due to FeeRateTooHigh
        vm.assume(_feeRate <= 5000);

        // Call initialize to set up the contract state
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {} catch {
            // If initialize reverts due to other constraints (e.g., AlreadyInitialized), we skip the test.
            return;
        }

        // Assert that the stored changeFee equals the provided _changeFee parameter.
        assertTrue(c.changeFee() == _changeFee);
    }
}

